"""Timesheet lines per worker, busiest first."""

from typing import List, Tuple
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from collections import Counter

Entry = Tuple[str, int, int]

def check_shifts(shifts: List[Shift]) -> None:
    """Refuse no shifts, or a shift with no worker name."""
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("a shift has no worker name")

def busiest(entry: Entry) -> Tuple[int, str]:
    """Sort key: most minutes first, then by name."""
    return (-entry[2], entry[0])

def worker_rows(shifts: List[Shift]) -> List[Entry]:
    """Name, shift count and minutes, busiest first."""
    totals = worker_minutes(shifts)
    tally = Counter(shift.worker for shift in shifts)
    rows = [
        (name, tally[name], totals[name]) for name in totals
    ]
    return sorted(rows, key=busiest)

def timesheet_line(
    name: str, count: int, minutes: int
) -> str:
    """One row such as Brisa with shift count and hours."""
    noun = "shift" if count == 1 else "shifts"
    hours = minutes / 60
    return f"{name}: {count} {noun}, {hours:.1f} hours"

def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    check_shifts(shifts)
    rows = worker_rows(shifts)
    return [timesheet_line(*entry) for entry in rows]

