# owner: platform
"""Tests for the weekly timesheet lines."""

import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

def make_shift(worker, day, start, stop):
    return Shift(worker, day, Span(start, stop))

class TimesheetLineTests(unittest.TestCase):
    def test_busiest_workers_first(self):
        shifts = [
            make_shift("Odell", "mon", 540, 780),
            make_shift("Odell", "tue", 540, 780),
            make_shift("Brisa", "mon", 540, 900),
            make_shift("Brisa", "tue", 540, 900),
            make_shift("Brisa", "wed", 540, 900),
            make_shift("Quill", "fri", 540, 1020),
            make_shift("Quill", "sat", 540, 810)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 3 shifts, 18.0 hours",
                "Quill: 2 shifts, 12.5 hours",
                "Odell: 2 shifts, 8.0 hours"
            ]
        )

    def test_ties_sorted_by_name(self):
        shifts = [
            make_shift("Zed", "mon", 540, 780),
            make_shift("Amir", "tue", 540, 780)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Amir: 1 shift, 4.0 hours",
                "Zed: 1 shift, 4.0 hours"
            ]
        )

    def test_hours_rounded_to_one_decimal(self):
        shifts = [make_shift("Nell", "mon", 540, 560)]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Nell: 1 shift, 0.3 hours"]
        )

    def test_overlapping_shifts_both_counted(self):
        shifts = [
            make_shift("Pim", "mon", 540, 720),
            make_shift("Pim", "mon", 600, 780)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Pim: 2 shifts, 6.0 hours"]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for worker in ("", "   "):
            with self.subTest(worker=worker):
                shift = make_shift(worker, "mon", 540, 600)
                with self.assertRaises(ValueError):
                    timesheet_lines([shift])
